# region: shape
def shape(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: render
def render(xs, floor_=6):
    return [v for v in xs if v >= floor_]

# region: intake
def intake(xs):
    return [v * v for v in xs[1:]]

# region: gather
def gather(xs):
    return [v * v for v in xs]

# region: digest
def digest(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: emit
def emit(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return emit(digest(gather(intake(render(shape(raw))))))

